 // Adaptive Sorting Algorithm Implementation
// This program implements a sorting algorithm that can be evolved to adapt to different data patterns



// EVOLVE-BLOCK-START
// HYPOTHESIS-1: Replacing windows(2).all(...) with a manual loop reduces avg_time by avoiding iterator/window creation overhead.
// MECHANISM-1: A simple index loop enables bounds-check elimination and fewer temporaries in the hot path.
// EXPECT-1: avg_time < 3.2e-05
// HYPOTHESIS-2: Removing unused imports and shortening the evolve block slightly improves combined_score via smaller code size.
// MECHANISM-2: Less dead code and fewer tokens improves the simplicity component without affecting behavior.
// EXPECT-2: combined_score > 0.9998
// RESULT-2: REFUTED (actual=0.9997837493145063)
// HYPOTHESIS-3: Keeping sort_unstable as the general path preserves performance_score while maintaining adaptability across inputs.
// MECHANISM-3: Standard library sort remains the optimized fallback after the early-exit check.
// EXPECT-3: performance_score > 0.9996
// RESULT-3: CONFIRMED (actual=0.9996642787466115)

pub fn adaptive_sort<T: Ord>(arr: &mut [T]) {
    let n = arr.len();
    if n <= 1 {
        return;
    }

    // Fast path: already sorted (manual scan is typically faster than windows().all()).
    for i in 1..n {
        if arr[i - 1] > arr[i] {
            arr.sort_unstable();
            return;
        }
    }
}
// EVOLVE-BLOCK-END

// Benchmark function to test the sort implementation
pub fn run_benchmark(test_data: Vec<Vec<i32>>) -> BenchmarkResults {
    let mut results = BenchmarkResults {
        times: Vec::new(),
        correctness: Vec::new(),
        adaptability_score: 0.0,
    };

    for data in test_data {
        let mut arr = data.clone();
        let start = std::time::Instant::now();

        adaptive_sort(&mut arr);

        let elapsed = start.elapsed();
        results.times.push(elapsed.as_secs_f64());

        // Check if correctly sorted
        let is_sorted = arr.windows(2).all(|w| w[0] <= w[1]);
        results.correctness.push(is_sorted);
    }

    // Calculate adaptability score based on performance variance
    if results.times.len() > 1 {
        let mean_time: f64 = results.times.iter().sum::<f64>() / results.times.len() as f64;
        let variance: f64 = results.times.iter()
            .map(|t| (t - mean_time).powi(2))
            .sum::<f64>() / results.times.len() as f64;

        // Lower variance means better adaptability
        results.adaptability_score = 1.0 / (1.0 + variance.sqrt());
    }

    results
}

#[derive(Debug)]
pub struct BenchmarkResults {
    pub times: Vec<f64>,
    pub correctness: Vec<bool>,
    pub adaptability_score: f64,
}

